#!/usr/bin/env python3
"""gelen klasöründeki medya dosyalarını tarihe göre arşivle."""

import os
import re
import shutil

MEDYA_EXT = {'.jpg', '.jpeg', '.png', '.mp4', '.mov'}
GELEN = 'gelen'
ARSIV   = 'arsiv'

# YYYYMMDD veya YYYY-MM-DD kalıbı – 20 ile başlayan 8 rakam
TARIH_RE = re.compile(r'\b(20\d{2})([-_])(\d{2})\2(\d{2})\b')

def bul_tarih(ad):
    """Dosya adından ilk YYYYMMDD/Y-m-d kalıbını yakala, (YYYY,MM,DD) döndür veya None."""
    m = TARIH_RE.search(ad)
    if not m:
        return None
    return int(m.group(1)), int(m.group(3)), int(m.group(4))

def medya_mi(ad):
    return ad.rsplit('.', 1)[-1].lower() in MEDYA_EXT if '.' in ad else False

def klasor_hazirl():
    os.makedirs(ARSIV, exist_ok=True)

def gonder(src, dst):
    """Dosyayı hedef klasöre taşı (aynı adla). Hedef klasör yoksa oluştur."""
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    shutil.move(src, dst)
    print(f'  {os.path.relpath(src)} → {os.path.relpath(dst)}')

def isle():
    klasor_hazirl()
    tarihsiz_dir = os.path.join(ARSIV, 'tarihsiz')

    for klasor_doz, alt_klasorler, dosyalar in os.walk(GELEN):
        for ad in sorted(dosyalar):
            src = os.path.join(klasor_doz, ad)
            rel = os.path.relpath(src, GELEN)

            # Medya değilse atla
            if not medya_mi(ad):
                continue

            tarih = bul_tarih(ad)
            if tarih:
                yy, mm, gg = tarih
                dst = os.path.join(ARSIV, yy, mm, gg, ad)
            else:
                dst = os.path.join(tarihsiz_dir, ad)

            gonder(src, dst)

    print('\n— Arşivleme tamamlandı —')

def kontrol():
    """Arşiv sonucunu ekrana bas."""
    print('\n=== Arşiv içeriği ===')
    for klasor_doz, alt_klasorler, dosyalar in os.walk(ARSIV):
        for ad in sorted(dosyalar):
            print(f'  {os.path.relpath(klasor_doz, ARSIV)}/{ad}')
            print(f'    boyut: {os.path.getsize(os.path.join(klasor_doz, ad))} B')
    # gelen klasörünün boş olup olmadığını da göster
    print('\n=== gelen (kalansız medya) ===')
    for klasor_doz, _, dosyalar in os.walk(GELEN):
        for ad in sorted(dosyalar):
            print(f'  {os.path.relpath(os.path.join(klasor_doz, ad), GELEN)}')

if __name__ == '__main__':
    isle()
    kontrol()

